#!/usr/bin/env python3
"""Compile read-only identity-led art briefs and exact reference hashes. Never submit or install."""
import datetime,hashlib,json
from pathlib import Path
from PIL import Image
P=Path(__file__).resolve().parent; BASE=P.parent; ROOT=BASE.parents[2]
def rel(v):return str(v.relative_to(ROOT))
def sha(v):return hashlib.sha256(v.read_bytes()).hexdigest()
retained={'doge':'Explicitly approved imperial reference; retain unchanged.','pnut':'Source-specific peanut relief already extends beyond the hero.','wif':'Actual source pink knit is carried into the full frame.','eacc':'Source energy silhouette and luminous field inform the entire frame.'}
designs={e['quoteKey']:e for e in json.loads((ROOT/'app/src/lib/carddex/pair-designs.json').read_text()) if e['category']=='memes'}
briefs={e['quoteKey']:e for n in ['identity-briefs.json','expansion-identity-briefs.json','expansion-direct-identity-briefs.json'] for e in json.loads((BASE/n).read_text())['entries']}
refs=json.loads((P/'reference-paths.json').read_text()); override=json.loads((BASE/'research/fartcoin-generation-override-approved.json').read_text());refs['fartcoin']=override['referencePath']
directions={}
for line in (P/'directions-source.tsv').read_text().splitlines():
 k,evidence,frame,materials,reverse,avoid=line.split('\t');directions[k]={'identityEvidence':evidence,'frontFrame':frame,'materials':materials,'reverseComposition':reverse,'identityExclusions':avoid}
assert set(directions)==set(designs)-set(retained),(set(directions)^set(designs)-set(retained))
assert len(designs)==66 and len(directions)==62
layout=json.loads((P/'layout-guide.json').read_text()); guides=layout['files']
common='This is a premium high-definition thin rounded trading-card skin, rendered directly front-on with the complete card visible and no perspective, case, slab, cast shadow or product mockup. Use only the exact supplied identity reference; preserve its actual facial features, silhouette, expression, pose, geometry and identity colors. Do not hallucinate detail missing from a low-resolution source. No generic royal four-point stars, laurel wreath, stock medallion oval, generic marble lattice, crown or Doge ornament. The design must be recognizably tailored through its perimeter geometry, material and relief, even if the hero were covered. No theme labels, platform names, new words, numbers, serials or footer slots. Only authentic lettering that belongs to the pinned source logo may remain; omit incidental prose/slogans unless separately approved as the exact identity mark. Keep the card thin, edges smooth and rounded, with even neutral light and no clipped ornament. Exact quotes and branding do not imply affiliation or issuer endorsement.'
frontgrid='The gray front wireframe is a GEOMETRY-ONLY guide, not a style reference. Preserve its exact63:88 rounded outline and all four shared empty content apertures: name x.10 y.055 w.80 h.06; creator art x.10 y.15 w.80 h.44; type x.10 y.615 w.80 h.034; description x.10 y.67 w.80 h.255. Keep the creator-art window completely blank and all name/type/description surfaces uniformly light ivory, untextured and free of imagery or letters for live dark text. Put identity artwork ONLY in the perimeter, corners, rails and gaps outside those apertures. No large front hero overlapping creator art. Ignore the guide gray colors; use the identity-specific materials.'
backgrid='The back wireframe gives ONLY the same thin rounded outer-card geometry. It does not prescribe a central circle, crest, star, frame language or hero position. Use the unique source-derived composition below. Match the accepted new front materials when it is supplied as a separate reference. Do not copy content apertures onto the back or borrow any old generic royal template.'
accepted={}
for n in ['accepted-pairs-51.json','accepted-pairs-38.json','accepted-pairs-final.json']:
 for e in json.loads((BASE/n).read_text())['acceptedPairs']:accepted[e['quoteKey']]=e
entries=[];requests=[]
for key in sorted(directions,key=lambda k:(k not in ['pepe','fone'],['pepe','fone'].index(k) if k in ['pepe','fone'] else k)):
 d=designs[key];b=briefs[key];v=directions[key];rf=ROOT/refs[key];assert rf.is_file(),rf
 with Image.open(rf) as im: dimensions=list(im.size);fmt=im.format
 ref={'path':rel(rf),'sha256':sha(rf),'dimensions':dimensions,'format':fmt,'status':'Pinned exact-identity reference visually compared; no generated source is used as identity evidence.'}
 if key=='fartcoin':assert ref['sha256']==override['sourceSha256'];ref['scopedOverride']=rel(BASE/'research/fartcoin-generation-override-approved.json')
 identity=v['identityEvidence']+' Identity-specific exclusions: '+v['identityExclusions']
 front='EDIT IMAGE 1, the gray layout wireframe. Preserve the exact rounded outer outline and FOUR EMPTY ivory rectangles at their EXACT positions and sizes. Do not add, split, move, shorten, cover or fill any rectangle. The huge middle creator-art rectangle MUST remain entirely blank. Replace ONLY the gray perimeter rails and gaps OUTSIDE all four empty rectangles with a premium thin trading-card frame. IMAGE 2 supplies abstract identity inspiration ONLY through these shapes and materials: '+v['frontFrame']+' MATERIALS: '+v['materials']+' DO NOT DRAW ANY WHOLE CHARACTER, HUMAN, ANIMAL, HEAD, FACE, EYES, BODY, PORTRAIT OR COMPLETE IDENTITY PICTURE ANYWHERE ON THIS FRONT. This front is a customizable frame only. Use source shapes as ABSTRACT perimeter contours, not pictures or miniature corner mascots. No images inside any of the four surfaces. Name, type and description panels must stay uniformly light ivory, untextured and clean for live dark text. No new or split panels, footer slots, words, numbers, labels, serials, full logos, laurel wreath, royal medal, generic star, crown, marble lattice, scene, perspective, thickness, case or slab. Crisp refined HD physical-material detail, smooth rounded thin edges, neutral even light and straight front view. Preserve IMAGE1 geometry while replacing its gray material only.'
 back='Create one BACK CARD SKIN. '+common+' '+identity+' '+backgrid+' UNIQUE REVERSE: '+v['reverseComposition']+' MATCHING MATERIALS: '+v['materials']
 entry={'quoteKey':key,'designKey':d['key'],'exactQuoteMint':d['quoteMint'],'sourceName':b['exactIdentity'],'sourceKind':b['kind'],'reference':ref,'direction':v,'commonLayout':{'frontGuide':guides['canonical-front-wireframe.png'],'backGuide':guides['canonical-back-wireframe.png']},'frontPrompt':front,'backPrompt':back,'status':'prepared only; no paid submission or acceptance change','currentPriorAcceptedPair':key in accepted}
 if key in ['ansem','michi']:entry['specificQualityGate']='ANSEM must keep human-faced minotaur, never a natural bull. MICHI must retain its actual raised-paw pose; compare native source before accepting.'
 if key=='pepe':entry['artInterpretation']='Small lily-pad/waterline relief is an explicit parent-requested frog-inspired design motif, not a claim that the source depicts a habitat.'
 entries.append(entry)
 for face,prompt in [('front',front),('back',back)]:requests.append({'requestId':f'tailoring-v2-{key}-{face}','quoteKey':key,'designKey':d['key'],'exactQuoteMint':d['quoteMint'],'face':face,'identityReference':ref,'layoutGuide':guides[f'canonical-{face}-wireframe.png'],'prompt':prompt,'matchingFrontReferenceRequiredForBack':face=='back','status':'unsubmitted; parent pilot/model gate must pass before batch submission'})
plan={'preparedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'READ-ONLY PREPARATION. No paid calls, acceptance writes, derivative replacement or deployment.','scope':{'totalMemeDesigns':66,'retained':retained,'redesignPairs':62,'redesignFaces':124,'categoryRule':'Includes two collector-identity entries CARDS and SV151 in the site meme catalogue; this does not assert they are issuer-affiliated.'},'sourcePolicy':'Use exact pinned source+SHA and geometric guide. Never use the prior Doge decoration as style conditioning. No world/mascot inferred from ticker. Geometry/material interpretations below are art direction from actual visible shapes; no affiliation, identity, or background claims.','candidateProvider':'Higgsfield','candidateModel':'Seedream5Flash (parent pilot under evaluation; this file is not a model/price authorization)','pilotOrder':['pepe-front','fone-front'],'frontPromptRevision':'strict-edit-image1-guide-first-identity-second-after-failed-pilot301-302','submissionGate':'Blocked until parent strict retry303/304 passes aperture/grid QA; no bulk execution authorized by these files.','parentBudgetConstraint':'Parent owns all paid calls. Do not submit wider batches until premium-quality pilot passes. Root is reallocating unused future/reserve within596.5 starting-balance maximum; unknown10 batches27.5 held. This plan authorizes no spend.','canonicalLayout':layout,'visualReferenceEvidence':['output/higgsfield/pair-identities-2026-10-30/integration/tailoring-audit/index.json','output/higgsfield/pair-identities-2026-10-30/integration/tailoring-audit/unseen-sources-01.jpg','output/higgsfield/pair-identities-2026-10-30/integration/tailoring-audit/unseen-sources-02.jpg'],'qualityGate':['Exact identity at native source resolution; reject substitutions, pose loss, invented accessories and incorrect logo geometry.','Distinctive frame geometry and materials must communicate this identity when central hero is covered; recolor+corner badge is insufficient.','All four front content surfaces remain fixed, empty and pale; no overlap, added footer slots or source text inside creator surfaces.','No repeated star/laurel/oval/marble fallback. Authentically source-derived circular/pixel/letter forms may remain where they are the identity itself.','Match front/back material language and keep smooth rounded thin edges; inspect actual canonical populated card at desktop/mobile before final exposure.','Only reviewed complete source pairs enter the acceptance manifests; retain approved old sources until replacements actually pass.'],'entries':entries,'requests':requests}
(P/'plan.json').write_text(json.dumps(plan,indent=2)+'\n')
lines=['# Meme Tailoring v2','',f"Prepared{len(entries)} identity-specific pairs /{len(requests)} faces from the66 exact pinned meme-catalogue references. DOGE, PNUT, WIF and EACC remain unchanged by explicit parent direction.",'','The canonical content positions are shared. Decorative frame geometry is not. Each brief has a specific visual mechanism from the actual reference, exact identity exclusions, front/back material continuity and source hashes. The guides are plain geometric conditioning images, not public card artwork. All public replacement art must come from Higgsfield after the parent quality pilot passes.','','No source acceptance, asset activation, generation, credit spend or deployment occurs in this plan.','','## Design directions','', '| Pair | Unique perimeter / material | Reverse composition |','| --- | --- | --- |']
for e in entries:lines.append(f"| {e['quoteKey'].upper()} | {e['direction']['frontFrame']} {e['direction']['materials']} | {e['direction']['reverseComposition']} |")
lines+=['','## Exact layout guide','',f"Front: `{guides['canonical-front-wireframe.png']['path']}` — SHA-256 `{guides['canonical-front-wireframe.png']['sha256']}`.",'',f"Back outline: `{guides['canonical-back-wireframe.png']['path']}` — SHA-256 `{guides['canonical-back-wireframe.png']['sha256']}`.",'','`plan.json` contains124 unsubmitted request briefs. Back requests need the newly accepted front as a matching-material reference. `pilot-fronts.json` is the parent-requested PEPE/FONE front-only pilot package. The complete plan supersedes the earlier ten-face prioritization without authorizing spending.','']
(P/'PLAN.md').write_text('\n'.join(lines).replace('Prepared62','Prepared 62').replace(' /124',' / 124').replace('the66','the 66').replace('contains124','contains 124'))
print(json.dumps({'memeCatalogue':len(designs),'retained':sorted(retained),'pairs':len(entries),'faces':len(requests),'pinnedReferences':len({e['reference']['path'] for e in entries}),'plan':rel(P/'plan.json')},indent=2))
